export BASH_FUNC_module%%='() {  if [ -z "${LMOD_SH_DBG_ON+x}" ]; then'
 case "$-" in 
 *v*x*)
export  __lmod_sh_dbg=''vx''
 ;;
 *v*)
export  __lmod_sh_dbg=''v''
 ;;
 *x*)
export  __lmod_sh_dbg=''x''
 ;;
 esac;
 fi;
 if [ -n "${__lmod_sh_dbg:-}" ]; then
 set +$__lmod_sh_dbg;
export  echo "Shell debugging temporarily silenced: export LMOD_SH_DBG_ON='1 for Lmod's output" 1>&2;'
 fi;
 eval "$($LMOD_CMD shell "$@")" && eval "$(${LMOD_SETTARG_CMD:-:} -s sh)";
export  __lmod_my_status='$?;'
 if [ -n "${__lmod_sh_dbg:-}" ]; then
 echo "Shell debugging restarted" 1>&2;
 set -$__lmod_sh_dbg;
 fi;
 unset __lmod_sh_dbg;
 return $__lmod_my_status
}
export BASH_FUNC_scl%%='() {  if [ "$1" = "load" -o "$1" = "unload" ]; then'
 eval "module $@";
 else
 /usr/bin/scl "$@";
 fi
}
